def find_inversions(n, a):
    # Check if the array is already sorted
    if all(a[i] <= a[i + 1] for i in range(n - 1)):
        return 0, []

    # Find all inversions
    inversions = []
    for i in range(n):
        for j in range(i + 1, n):
            if a[i] > a[j]:
                inversions.append((i + 1, j + 1))

    # Check if we can sort the array using the inversions
    for i in range(n):
        for j in range(i + 1, n):
            if a[i] >  a[j]:
                for u, v in inversions:
                    if a[u - 1] > a[v - 1]:
                        a[u - 1], a[v - 1] = a[v - 1], a[u - 1]
                        if all(a[k] <= a[k + 1] for k in range(n - 1)):
                            return len(inversions), inversions
                        else:
                            return -1, []
    return len(inversions), inversions

